CREATE OR REPLACE FUNCTION public.associar_checklist_veiculo(_checklist_id uuid, _bem_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE checklist public.checklists_veiculos%ROWTYPE; bem public.bens%ROWTYPE; termo public.recebimentos_veiculos%ROWTYPE; nome_local text;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Entre novamente para associar o checklist.'; END IF;
 SELECT * INTO checklist FROM public.checklists_veiculos WHERE id = _checklist_id FOR UPDATE;
 IF NOT FOUND OR NOT (checklist.user_id = auth.uid() OR public.has_role(auth.uid(), 'admin'::public.app_role)) THEN
   RAISE EXCEPTION 'Checklist não disponível para esta conta.';
 END IF;
 IF checklist.bem_id IS NOT NULL THEN RAISE EXCEPTION 'Este checklist já foi associado a um patrimônio.'; END IF;
 SELECT * INTO bem FROM public.bens WHERE id = _bem_id FOR SHARE;
 IF NOT FOUND OR bem.sala_id IS NULL THEN RAISE EXCEPTION 'Veículo sem Local Físico disponível.'; END IF;
 IF NOT public.pode_ver_sala(auth.uid(), bem.sala_id) THEN RAISE EXCEPTION 'Você não tem acesso ao Local Físico deste veículo.'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(_bem_id::text, 815));
 IF EXISTS (SELECT 1 FROM public.recebimentos_veiculos WHERE bem_id = _bem_id) THEN
   RAISE EXCEPTION 'Este veículo já possui um termo. Escolha outro patrimônio para não sobrescrever o recebimento existente.';
 END IF;
 SELECT nome INTO nome_local FROM public.salas WHERE id = bem.sala_id;
 INSERT INTO public.recebimentos_veiculos(bem_id, dados, atualizado_por, atualizado_em)
 VALUES (_bem_id, jsonb_build_object('orgao', 'PREFEITURA MUNICIPAL DE ITAJUBÁ', 'cidade', 'Itajubá') || checklist.dados || jsonb_build_object('local_fisico', nome_local, 'data_termo', to_char(now() AT TIME ZONE 'America/Sao_Paulo', 'YYYY-MM-DD')), auth.uid(), now())
 RETURNING * INTO termo;
 UPDATE public.checklists_veiculos SET bem_id = _bem_id, atualizado_em = now() WHERE id = _checklist_id;
 RETURN to_jsonb(termo);
END;
$function$

CREATE OR REPLACE FUNCTION public.associar_checklist_veiculo_por_red(_checklist_id uuid, _codigo_red text, _sala_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
 checklist public.checklists_veiculos%ROWTYPE;
 bem public.bens%ROWTYPE;
 codigo text;
 modelo text;
 descricao_veiculo text;
 valor_texto text;
 valor_veiculo numeric;
 termo jsonb;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Entre novamente para associar o checklist.'; END IF;
 SELECT * INTO checklist FROM public.checklists_veiculos WHERE id = _checklist_id FOR UPDATE;
 IF NOT FOUND OR NOT (checklist.user_id = auth.uid() OR public.has_role(auth.uid(), 'admin'::public.app_role)) THEN
  RAISE EXCEPTION 'Checklist não disponível para esta conta.';
 END IF;
 IF checklist.bem_id IS NOT NULL THEN RAISE EXCEPTION 'Este checklist já foi associado a um patrimônio.'; END IF;
 codigo := public.chave_codigo_red_importacao(_codigo_red);
 IF codigo IS NULL OR codigo !~ '^[0-9]{1,50}$' THEN RAISE EXCEPTION 'Informe um código RED numérico válido.'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('codigo-red:' || codigo, 0));
 SELECT * INTO bem FROM public.bens WHERE public.chave_codigo_red_importacao(codigo_red) = codigo;
 IF FOUND THEN
  IF bem.sala_id IS NULL OR NOT public.pode_ver_sala(auth.uid(), bem.sala_id) THEN
   RAISE EXCEPTION 'Este código RED já está cadastrado, mas não está disponível em um Local Físico acessível à sua conta. Solicite a conferência ao administrador.';
  END IF;
 ELSE
  IF NOT public.can_edit(auth.uid()) THEN RAISE EXCEPTION 'O código RED ainda não está cadastrado. Peça a um administrador ou operador para cadastrá-lo.'; END IF;
  IF _sala_id IS NULL OR NOT public.pode_ver_sala(auth.uid(), _sala_id) THEN RAISE EXCEPTION 'Escolha um Local Físico disponível para cadastrar o veículo.'; END IF;
  PERFORM 1 FROM public.salas WHERE id = _sala_id FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Local Físico não encontrado.'; END IF;
  modelo := btrim(coalesce(checklist.dados->>'modelo_veiculo', ''));
  IF modelo = '' THEN RAISE EXCEPTION 'Preencha o modelo do veículo no checklist antes de cadastrar o código RED.'; END IF;
  valor_texto := btrim(coalesce(checklist.dados->>'valor', ''));
  IF valor_texto = '' THEN valor_veiculo := 0;
  ELSE
   IF valor_texto !~ '^[0-9]+([.][0-9]{1,2})?$' OR length(valor_texto) > 13 THEN RAISE EXCEPTION 'Confira o campo Valor do checklist.'; END IF;
   valor_veiculo := valor_texto::numeric;
   IF valor_veiculo >= 10000000000 THEN RAISE EXCEPTION 'O valor do veículo excede o limite permitido.'; END IF;
  END IF;
  descricao_veiculo := concat_ws(E'\n', 'VEÍCULO/MODELO: ' || modelo,
   CASE WHEN btrim(coalesce(checklist.dados->>'ano_modelo','')) <> '' THEN 'ANO/MOD: ' || (checklist.dados->>'ano_modelo') END,
   CASE WHEN btrim(coalesce(checklist.dados->>'chassi','')) <> '' THEN 'CHASSI: ' || (checklist.dados->>'chassi') END,
   CASE WHEN btrim(coalesce(checklist.dados->>'motor','')) <> '' THEN 'MOTOR Nº: ' || (checklist.dados->>'motor') END,
   CASE WHEN btrim(coalesce(checklist.dados->>'renavam','')) <> '' THEN 'RENAVAM: ' || (checklist.dados->>'renavam') END,
   CASE WHEN btrim(coalesce(checklist.dados->>'placa','')) <> '' THEN 'PLACA: ' || (checklist.dados->>'placa') END,
   CASE WHEN btrim(coalesce(checklist.dados->>'km','')) <> '' THEN 'KM: ' || (checklist.dados->>'km') END);
  INSERT INTO public.bens(user_id, sala_id, codigo_red, descricao, valor, tipo)
   VALUES(auth.uid(), _sala_id, codigo, descricao_veiculo, valor_veiculo, 'VEÍCULO') RETURNING * INTO bem;
 END IF;
 termo := public.associar_checklist_veiculo(_checklist_id, bem.id);
 RETURN jsonb_build_object('bem', to_jsonb(bem), 'termo', termo);
END;
$function$

CREATE OR REPLACE FUNCTION public.buscar_ultima_transferencia(_codigo text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  transferencia uuid;
  resultado jsonb;
BEGIN
  IF auth.uid() IS NULL OR NOT public.can_edit(auth.uid()) THEN RAISE EXCEPTION 'Sem permissão para consultar transferências'; END IF;
  IF _codigo IS NULL OR btrim(_codigo) !~ '^[0-9]+$' THEN RAISE EXCEPTION 'Digite apenas um código RED, somente com números'; END IF;
  SELECT transferencia_id INTO transferencia FROM public.transferencias_bens_itens
    WHERE codigo_red = btrim(_codigo) ORDER BY id DESC LIMIT 1;
  IF NOT FOUND THEN RETURN NULL; END IF;
  SELECT jsonb_build_object(
    'id', transferencia, 'numero', min(t.numero), 'ano', min(t.termo_ano),
    'data', min(t.created_at), 'destino', min(t.destino_nome),
    'itens', jsonb_agg(jsonb_build_object(
      'id', t.bem_id, 'codigo_red', t.codigo_red, 'descricao', t.descricao, 'valor', t.valor,
      'origem', t.origem_nome, 'estornado_em', t.estornado_em,
      'impedimento', CASE
        WHEN t.estornado_em IS NOT NULL THEN 'Já estornado'
        WHEN b.id IS NULL THEN 'Bem removido'
        WHEN b.sala_id IS DISTINCT FROM t.destino_sala_id OR b.importacao_id IS DISTINCT FROM t.transferencia_id THEN 'Bem movimentado após esta transferência'
        WHEN t.origem_sala_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.salas s WHERE s.id = t.origem_sala_id) THEN 'Sala de origem removida'
        WHEN EXISTS (SELECT 1 FROM public.bens outro WHERE outro.id <> t.bem_id AND outro.codigo_red = t.codigo_red AND outro.sala_id IS NOT DISTINCT FROM t.origem_sala_id) THEN 'O local de origem já contém este código RED'
        ELSE NULL END
    ) ORDER BY t.codigo_red, t.id)
  ) INTO resultado FROM public.transferencias_bens_itens t LEFT JOIN public.bens b ON b.id = t.bem_id
    WHERE t.transferencia_id = transferencia;
  RETURN resultado;
END;
$function$

CREATE OR REPLACE FUNCTION public.chat_identificar_usuario()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  SELECT COALESCE(NULLIF(btrim(p.nome), ''), NULLIF(btrim(p.login), ''), 'Usuário') INTO NEW.nome FROM public.profiles p WHERE p.id = NEW.user_id;
  NEW.nome := COALESCE(NEW.nome, 'Usuário');
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.chat_notificar_push()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE segredo text;
BEGIN
  SELECT dispatch_token INTO segredo FROM public.chat_push_config WHERE id = true;
  PERFORM net.http_post(
    url := 'https://wdkimydszbyxnmduedid.supabase.co/functions/v1/chat-push',
    headers := jsonb_build_object('Content-Type', 'application/json'),
    body := jsonb_build_object('action', 'dispatch', 'messageId', NEW.id, 'token', segredo),
    timeout_milliseconds := 10000
  );
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'Não foi possível agendar o aviso do chat: %', SQLERRM;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.consultar_bens_importacao(_bens jsonb)
 RETURNS TABLE(id uuid, sala_id uuid, codigo_red text, sala_nome text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NULL OR NOT public.can_edit(auth.uid()) THEN
    RAISE EXCEPTION 'Sem permissão para importar';
  END IF;
  IF jsonb_typeof(_bens) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'Lista de bens inválida';
  END IF;
  RETURN QUERY SELECT b.id, b.sala_id, b.codigo_red, coalesce(s.nome, 'Sem sala')
    FROM public.bens b LEFT JOIN public.salas s ON s.id = b.sala_id
    WHERE public.chave_codigo_red_importacao(b.codigo_red) IN (
      SELECT public.chave_codigo_red_importacao(x->>'codigo_red') FROM jsonb_array_elements(_bens) x
    ) ORDER BY b.id;
END;
$function$

CREATE OR REPLACE FUNCTION public.consultar_proximo_numero_transferencia()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  proximo bigint;
BEGIN
  IF auth.uid() IS NULL OR NOT public.can_edit(auth.uid()) THEN
    RAISE EXCEPTION 'Sem permissão para gerar transferência';
  END IF;
  SELECT ultimo_numero + 1 INTO proximo FROM public.termos_numeracao_contador WHERE id = true;
  IF proximo IS NULL THEN RAISE EXCEPTION 'Numeração indisponível'; END IF;
  RETURN jsonb_build_object('numero', proximo, 'ano', extract(year FROM timezone('America/Sao_Paulo', now()))::integer);
END;
$function$

CREATE OR REPLACE FUNCTION public.criar_termo_bens_sala(_sala uuid, _itens uuid[], _pedido uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  local_sala public.salas%ROWTYPE;
  dept public.departamentos%ROWTYPE;
  lote public.importacoes%ROWTYPE;
  quantidade integer;
  itens_snapshot jsonb;
  responsavel jsonb;
  conflito jsonb;
BEGIN
  IF auth.uid() IS NULL OR NOT public.can_edit(auth.uid()) THEN
    RAISE EXCEPTION 'Sem permissão para criar termos de responsabilidade';
  END IF;
  IF _sala IS NULL OR _pedido IS NULL OR NOT public.pode_ver_sala(auth.uid(), _sala) THEN
    RAISE EXCEPTION 'Selecione uma sala disponível para sua conta';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(_pedido::text, 0));
  SELECT * INTO lote FROM public.importacoes WHERE id = _pedido;
  IF FOUND THEN
    IF lote.user_id IS DISTINCT FROM auth.uid() OR lote.sala_id IS DISTINCT FROM _sala OR lote.termo_snapshot->>'tipo_documento' IS DISTINCT FROM 'novo_termo' THEN
      RAISE EXCEPTION 'Pedido inválido';
    END IF;
    RETURN to_jsonb(lote);
  END IF;
  quantidade := coalesce(cardinality(_itens), 0);
  IF quantidade < 1 OR quantidade > 500 THEN
    RAISE EXCEPTION 'Selecione de 1 a 500 bens por termo';
  END IF;
  IF (SELECT count(DISTINCT id) FROM unnest(_itens) AS t(id)) <> quantidade THEN
    RAISE EXCEPTION 'Lista de bens inválida ou repetida';
  END IF;
  SELECT * INTO local_sala FROM public.salas WHERE id = _sala FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Sala não encontrada'; END IF;
  PERFORM b.id FROM public.bens b WHERE b.id = ANY(_itens) ORDER BY b.id FOR SHARE;
  IF (SELECT count(*) FROM public.bens b WHERE b.id = ANY(_itens) AND b.sala_id = _sala) <> quantidade THEN
    RAISE EXCEPTION 'Um bem foi removido ou não está nesta sala. Atualize a lista e selecione novamente';
  END IF;
  conflito := public.bem_em_outro_termo_da_sala(_sala, _itens, _pedido);
  IF conflito IS NOT NULL THEN
    RAISE EXCEPTION 'O bem % já está no termo % desta sala. Um bem só pode estar em outro termo da mesma sala se tiver ido para outra sala e retornado depois', conflito->>'codigo_red', conflito->>'termo';
  END IF;
  SELECT * INTO dept FROM public.departamentos WHERE id = local_sala.departamento_id;
  responsavel := public.dados_responsavel_sala_termo(_sala);
  SELECT jsonb_agg(jsonb_build_object('codigo_red', b.codigo_red, 'descricao', b.descricao,
    'valor', b.valor, 'incorporacao', b.incorporacao, 'tipo', b.tipo) ORDER BY b.codigo_red)
    INTO itens_snapshot FROM public.bens b WHERE b.id = ANY(_itens);
  INSERT INTO public.importacoes(id, sala_id, user_id, arquivo, termo_ano, termo_snapshot)
  VALUES (_pedido, _sala, auth.uid(), 'Novo termo de responsabilidade',
    extract(year FROM timezone('America/Sao_Paulo', now()))::integer,
    jsonb_build_object('tipo_documento', 'novo_termo', 'bem_ids', to_jsonb(_itens),
      'local', local_sala.nome, 'endereco', coalesce(local_sala.endereco, ''),
      'historico', 'Termo de responsabilidade de ' || quantidade || ' bem(ns) já pertencente(s) ao Local Físico. Sem movimentação patrimonial.',
      'data_origem', to_char(timezone('America/Sao_Paulo', now()), 'DD/MM/YYYY'),
      'data_termo', to_char(timezone('America/Sao_Paulo', now()), 'DD/MM/YYYY'),
      'departamento', coalesce(dept.departamento, ''), 'diretor', coalesce(dept.diretor, ''),
      'almoxarifado', coalesce(dept.almoxarifado, ''), 'endereco_departamento', coalesce(dept.endereco, ''),
      'bens', itens_snapshot) || responsavel)
  RETURNING * INTO lote;
  RETURN to_jsonb(lote);
END;
$function$

CREATE OR REPLACE FUNCTION public.criar_termo_bens_sala(_sala uuid, _itens uuid[], _pedido uuid, _aceitar_repetidos boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  local_sala public.salas%ROWTYPE;
  dept public.departamentos%ROWTYPE;
  lote public.importacoes%ROWTYPE;
  quantidade integer;
  itens_snapshot jsonb;
  responsavel jsonb;
