BEGIN
  IF auth.uid() IS NULL OR NOT public.can_edit(auth.uid()) THEN
    RAISE EXCEPTION 'Sem permissão para criar termos de responsabilidade';
  END IF;
  IF _sala IS NULL OR _pedido IS NULL OR NOT public.pode_ver_sala(auth.uid(), _sala) THEN
    RAISE EXCEPTION 'Selecione uma sala disponível para sua conta';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(_pedido::text, 0));
  SELECT * INTO lote FROM public.importacoes WHERE id = _pedido;
  IF FOUND THEN
    IF lote.user_id IS DISTINCT FROM auth.uid() OR lote.sala_id IS DISTINCT FROM _sala OR lote.termo_snapshot->>'tipo_documento' IS DISTINCT FROM 'novo_termo' THEN
      RAISE EXCEPTION 'Pedido inválido';
    END IF;
    RETURN to_jsonb(lote);
  END IF;
  quantidade := coalesce(cardinality(_itens), 0);
  IF quantidade < 1 OR quantidade > 500 THEN
    RAISE EXCEPTION 'Selecione de 1 a 500 bens por termo';
  END IF;
  IF (SELECT count(DISTINCT id) FROM unnest(_itens) AS t(id)) <> quantidade THEN
    RAISE EXCEPTION 'Lista de bens inválida ou repetida';
  END IF;
  SELECT * INTO local_sala FROM public.salas WHERE id = _sala FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Sala não encontrada'; END IF;
  PERFORM b.id FROM public.bens b WHERE b.id = ANY(_itens) ORDER BY b.id FOR SHARE;
  IF (SELECT count(*) FROM public.bens b WHERE b.id = ANY(_itens) AND b.sala_id = _sala) <> quantidade THEN
    RAISE EXCEPTION 'Um bem foi removido ou não está nesta sala. Atualize a lista e selecione novamente';
  END IF;
  conflito := public.bem_em_outro_termo_da_sala(_sala, _itens, _pedido);
  IF conflito IS NOT NULL AND NOT coalesce(_aceitar_repetidos, false) THEN
    RAISE EXCEPTION 'O bem % já está no termo % desta sala. Um bem só pode estar em outro termo da mesma sala se tiver ido para outra sala e retornado depois', conflito->>'codigo_red', conflito->>'termo';
  END IF;
  SELECT * INTO dept FROM public.departamentos WHERE id = local_sala.departamento_id;
  responsavel := public.dados_responsavel_sala_termo(_sala);
  SELECT jsonb_agg(jsonb_build_object('codigo_red', b.codigo_red, 'descricao', b.descricao,
    'valor', b.valor, 'incorporacao', b.incorporacao, 'tipo', b.tipo) ORDER BY b.codigo_red)
    INTO itens_snapshot FROM public.bens b WHERE b.id = ANY(_itens);
  INSERT INTO public.importacoes(id, sala_id, user_id, arquivo, termo_ano, termo_snapshot)
  VALUES (_pedido, _sala, auth.uid(), 'Novo termo de responsabilidade',
    extract(year FROM timezone('America/Sao_Paulo', now()))::integer,
    jsonb_build_object('tipo_documento', 'novo_termo', 'bem_ids', to_jsonb(_itens),
      'local', local_sala.nome, 'endereco', coalesce(local_sala.endereco, ''),
      'historico', 'Termo de responsabilidade de ' || quantidade || ' bem(ns) já pertencente(s) ao Local Físico. Sem movimentação patrimonial.',
      'data_origem', to_char(timezone('America/Sao_Paulo', now()), 'DD/MM/YYYY'),
      'data_termo', to_char(timezone('America/Sao_Paulo', now()), 'DD/MM/YYYY'),
      'departamento', coalesce(dept.departamento, ''), 'diretor', coalesce(dept.diretor, ''),
      'almoxarifado', coalesce(dept.almoxarifado, ''), 'endereco_departamento', coalesce(dept.endereco, ''),
      'bens', itens_snapshot) || responsavel)
  RETURNING * INTO lote;
  RETURN to_jsonb(lote);
END;
$function$

CREATE OR REPLACE FUNCTION public.dados_responsavel_sala_termo(_sala_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _sala public.salas%ROWTYPE;
  _nome text;
  _cpf text;
  _nome_sala text;
BEGIN
  IF auth.uid() IS NULL OR NOT public.can_edit(auth.uid()) THEN
    RAISE EXCEPTION 'Você não tem permissão para consultar o responsável pela sala.';
  END IF;
  SELECT * INTO _sala FROM public.salas WHERE id = _sala_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Sala não encontrada.'; END IF;
  _nome_sala := nullif(btrim(_sala.responsavel), '');
  SELECT p.nome, p.cpf INTO _nome, _cpf
    FROM public.user_salas us JOIN public.profiles p ON p.id = us.user_id
    WHERE us.sala_id = _sala_id AND nullif(btrim(p.nome), '') IS NOT NULL
    ORDER BY (lower(btrim(p.nome)) = lower(coalesce(_nome_sala, ''))) DESC, p.created_at DESC, p.id
    LIMIT 1;
  IF _nome_sala IS NOT NULL AND lower(btrim(coalesce(_nome, ''))) <> lower(_nome_sala) THEN
    _cpf := '';
  END IF;
  RETURN jsonb_build_object('responsavel', coalesce(_nome_sala, _nome, ''), 'cpf', coalesce(_cpf, ''));
END;
$function$

CREATE OR REPLACE FUNCTION public.emitir_retirada_veiculo(_bem_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE documento public.retiradas_veiculos%ROWTYPE; proximo bigint;
BEGIN
  IF auth.uid() IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.bens b WHERE b.id = _bem_id AND b.sala_id IS NOT NULL
      AND public.pode_ver_sala(auth.uid(), b.sala_id)
  ) THEN RAISE EXCEPTION 'Você não tem permissão para emitir a retirada deste veículo.'; END IF;
  PERFORM 1 FROM public.recebimentos_veiculos WHERE bem_id = _bem_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Salve o recebimento do veículo antes de emitir a retirada.'; END IF;
  SELECT * INTO documento FROM public.retiradas_veiculos WHERE bem_id = _bem_id;
  IF FOUND THEN RETURN to_jsonb(documento); END IF;
  UPDATE public.termos_numeracao_contador SET ultimo_numero = ultimo_numero + 1
    WHERE id = true RETURNING ultimo_numero INTO proximo;
  IF NOT FOUND THEN RAISE EXCEPTION 'Numeração indisponível'; END IF;
  INSERT INTO public.retiradas_veiculos (bem_id, numero, ano, criado_por)
  VALUES (_bem_id, proximo, extract(year FROM now() AT TIME ZONE 'America/Sao_Paulo')::integer, auth.uid())
  RETURNING * INTO documento;
  RETURN to_jsonb(documento);
END;
$function$

CREATE OR REPLACE FUNCTION public.estornar_bens_inserviveis(_solicitacoes uuid[], _sala_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _quantidade integer;
  _validos integer;
BEGIN
  IF auth.uid() IS NULL OR _sala_id IS NULL OR NOT public.pode_ver_sala(auth.uid(), _sala_id) THEN
    RAISE EXCEPTION 'Você não tem permissão para estornar bens deste local.';
  END IF;
  _quantidade := cardinality(_solicitacoes);
  IF _quantidade IS NULL OR _quantidade < 1 OR _quantidade > 1000 OR EXISTS (SELECT 1 FROM unnest(_solicitacoes) AS ids(id) WHERE id IS NULL) OR (SELECT count(DISTINCT id) FROM unnest(_solicitacoes) AS ids(id)) <> _quantidade THEN
    RAISE EXCEPTION 'Selecione de 1 a 1000 bens distintos para estornar.';
  END IF;
  PERFORM b.id FROM public.bens b
    WHERE b.id IN (SELECT s.bem_id FROM public.solicitacoes_bens s WHERE s.id = ANY(_solicitacoes))
    ORDER BY b.id FOR UPDATE;
  PERFORM s.id FROM public.solicitacoes_bens s WHERE s.id = ANY(_solicitacoes) ORDER BY s.id FOR UPDATE;
  SELECT count(*) INTO _validos FROM public.solicitacoes_bens s
    JOIN public.bens b ON b.id = s.bem_id
    WHERE s.id = ANY(_solicitacoes) AND s.ativa AND s.tipo = 'inservivel'
      AND s.sala_id = _sala_id AND b.sala_id = _sala_id;
  IF _validos <> _quantidade THEN
    RAISE EXCEPTION 'Algum bem não está mais pendente como inservível neste local. Feche e abra novamente o relatório antes de tentar de novo.';
  END IF;
  UPDATE public.solicitacoes_bens SET ativa = false, updated_at = clock_timestamp()
    WHERE id = ANY(_solicitacoes) AND ativa AND tipo = 'inservivel' AND sala_id = _sala_id;
  RETURN _quantidade;
END;
$function$

CREATE OR REPLACE FUNCTION public.estornar_solicitacoes_transferencia(_solicitacoes uuid[], _sala_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _quantidade integer;
  _validos integer;
BEGIN
  IF auth.uid() IS NULL OR _sala_id IS NULL OR NOT public.pode_ver_sala(auth.uid(), _sala_id) THEN
    RAISE EXCEPTION 'Você não tem permissão para estornar solicitações deste local.';
  END IF;
  _quantidade := cardinality(_solicitacoes);
  IF _quantidade IS NULL OR _quantidade < 1 OR _quantidade > 1000
    OR EXISTS (SELECT 1 FROM unnest(_solicitacoes) AS ids(id) WHERE id IS NULL)
    OR (SELECT count(DISTINCT id) FROM unnest(_solicitacoes) AS ids(id)) <> _quantidade THEN
    RAISE EXCEPTION 'Selecione de 1 a 1000 bens distintos para estornar.';
  END IF;
  PERFORM b.id FROM public.bens b
    WHERE b.id IN (SELECT s.bem_id FROM public.solicitacoes_bens s WHERE s.id = ANY(_solicitacoes))
    ORDER BY b.id FOR UPDATE;
  PERFORM s.id FROM public.solicitacoes_bens s
    WHERE s.id = ANY(_solicitacoes) ORDER BY s.id FOR UPDATE;
  SELECT count(*) INTO _validos FROM public.solicitacoes_bens s
    JOIN public.bens b ON b.id = s.bem_id
    WHERE s.id = ANY(_solicitacoes) AND s.ativa AND s.tipo = 'transferencia'
      AND s.sala_id = _sala_id AND b.sala_id = _sala_id;
  IF _validos <> _quantidade THEN
    RAISE EXCEPTION 'Algum bem não está mais pendente para transferência neste local. Feche e abra novamente o relatório antes de tentar de novo.';
  END IF;
  UPDATE public.solicitacoes_bens SET ativa = false, updated_at = clock_timestamp()
    WHERE id = ANY(_solicitacoes) AND ativa AND tipo = 'transferencia' AND sala_id = _sala_id;
  RETURN _quantidade;
END;
$function$

CREATE OR REPLACE FUNCTION public.estornar_transferencia(_transferencia uuid, _itens uuid[], _pedido uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  quantidade integer;
  ja_feitos integer;
BEGIN
  IF auth.uid() IS NULL OR NOT public.can_edit(auth.uid()) THEN RAISE EXCEPTION 'Sem permissão para estornar transferências'; END IF;
  IF _transferencia IS NULL OR _pedido IS NULL THEN RAISE EXCEPTION 'Pedido de estorno inválido'; END IF;
  quantidade := coalesce(cardinality(_itens), 0);
  IF quantidade < 1 OR quantidade > 500 OR (SELECT count(DISTINCT x) FROM unnest(_itens) x) <> quantidade THEN RAISE EXCEPTION 'Selecione de 1 a 500 bens diferentes'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(_pedido::text, 0));
  SELECT count(*) INTO ja_feitos FROM public.transferencias_bens_itens WHERE estorno_pedido = _pedido;
  IF ja_feitos > 0 THEN
    IF ja_feitos <> quantidade OR EXISTS (SELECT 1 FROM public.transferencias_bens_itens WHERE estorno_pedido = _pedido AND (transferencia_id <> _transferencia OR estornado_por <> auth.uid() OR NOT (bem_id = ANY(_itens)))) THEN
      RAISE EXCEPTION 'Este pedido pertence a outro estorno';
    END IF;
    RETURN jsonb_build_object('quantidade', ja_feitos);
  END IF;
  PERFORM s.id FROM public.salas s WHERE s.id IN (
    SELECT origem_sala_id FROM public.transferencias_bens_itens WHERE transferencia_id = _transferencia AND bem_id = ANY(_itens)
    UNION SELECT destino_sala_id FROM public.transferencias_bens_itens WHERE transferencia_id = _transferencia AND bem_id = ANY(_itens)
  ) ORDER BY s.id FOR UPDATE;
  PERFORM b.id FROM public.bens b WHERE b.id = ANY(_itens) ORDER BY b.id FOR UPDATE;
  PERFORM t.id FROM public.transferencias_bens_itens t WHERE t.transferencia_id = _transferencia AND t.bem_id = ANY(_itens) ORDER BY t.id FOR UPDATE;
  IF (SELECT count(*) FROM public.transferencias_bens_itens t JOIN public.bens b ON b.id = t.bem_id
    WHERE t.transferencia_id = _transferencia AND t.bem_id = ANY(_itens) AND t.estornado_em IS NULL
      AND b.sala_id = t.destino_sala_id AND b.importacao_id = t.transferencia_id
      AND (t.origem_sala_id IS NULL OR EXISTS (SELECT 1 FROM public.salas s WHERE s.id = t.origem_sala_id))) <> quantidade THEN
    RAISE EXCEPTION 'Um item já foi estornado, removido ou movimentado, ou sua sala de origem foi removida. Busque novamente antes de estornar';
  END IF;
  IF EXISTS (SELECT 1 FROM public.transferencias_bens_itens t JOIN public.bens b
    ON b.codigo_red = t.codigo_red AND b.sala_id IS NOT DISTINCT FROM t.origem_sala_id AND b.id <> t.bem_id
    WHERE t.transferencia_id = _transferencia AND t.bem_id = ANY(_itens)) THEN
    RAISE EXCEPTION 'A sala de origem já contém um dos códigos RED selecionados. Nenhum item foi estornado';
  END IF;
  UPDATE public.bens b SET sala_id = t.origem_sala_id,
    importacao_id = (SELECT i.id FROM public.importacoes i WHERE i.id = t.origem_importacao_id AND i.sala_id IS NOT DISTINCT FROM t.origem_sala_id),
    conferido = false, conferencia_finalizada = false
  FROM public.transferencias_bens_itens t WHERE t.transferencia_id = _transferencia AND t.bem_id = ANY(_itens) AND b.id = t.bem_id;
  UPDATE public.solicitacoes_bens SET ativa = false, updated_at = now() WHERE ativa AND bem_id = ANY(_itens);
  UPDATE public.transferencias_bens_itens SET estornado_em = now(), estornado_por = auth.uid(), estorno_pedido = _pedido
    WHERE transferencia_id = _transferencia AND bem_id = ANY(_itens);
  RETURN jsonb_build_object('quantidade', quantidade);
END;
$function$

CREATE OR REPLACE FUNCTION public.excluir_importacoes_sala(_sala_id uuid, _modo text, _importacao_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM id FROM public.salas WHERE id = _sala_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Local não encontrado'; END IF;
  IF _modo = 'todas' THEN
    DELETE FROM public.bens WHERE sala_id = _sala_id;
    DELETE FROM public.importacoes WHERE sala_id = _sala_id;
  ELSIF _modo = 'anteriores' THEN
    DELETE FROM public.bens WHERE sala_id = _sala_id AND importacao_id IS NULL;
  ELSIF _modo = 'uma' AND _importacao_id IS NOT NULL THEN
    DELETE FROM public.importacoes WHERE sala_id = _sala_id AND id = _importacao_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Importação não encontrada neste local'; END IF;
  ELSE
    RAISE EXCEPTION 'Selecione uma importação';
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.excluir_sala_vazia(_sala_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.can_edit(auth.uid()) THEN
    RAISE EXCEPTION 'Apenas administradores e operadores podem excluir salas';
  END IF;
  PERFORM id FROM public.salas WHERE id = _sala_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Sala não encontrada ou acesso não autorizado';
  END IF;
  IF EXISTS (SELECT 1 FROM public.bens WHERE sala_id = _sala_id) THEN
    RAISE EXCEPTION 'Esta sala possui bens e não pode ser excluída';
  END IF;
  DELETE FROM public.salas WHERE id = _sala_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.excluir_termo_sala(_termo uuid, _sala uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  documento jsonb;
  devolvidos integer := 0;
  desvinculados integer := 0;
  pedido uuid := gen_random_uuid();
BEGIN
  IF auth.uid() IS NULL OR NOT public.can_edit(auth.uid()) THEN
    RAISE EXCEPTION 'Você não tem permissão para excluir termos';
  END IF;
  IF _termo IS NULL OR _sala IS NULL THEN RAISE EXCEPTION 'Informe o termo e a sala'; END IF;
  PERFORM s.id FROM public.salas s WHERE s.id = _sala OR s.id IN (
    SELECT t.origem_sala_id FROM public.transferencias_bens_itens t
    WHERE t.transferencia_id = _termo AND t.estornado_em IS NULL
  ) ORDER BY s.id FOR UPDATE;
  PERFORM b.id FROM public.bens b WHERE b.importacao_id = _termo OR b.id IN (
    SELECT t.bem_id FROM public.transferencias_bens_itens t
    WHERE t.transferencia_id = _termo AND t.estornado_em IS NULL
  ) ORDER BY b.id FOR UPDATE;
  SELECT i.termo_snapshot INTO documento FROM public.importacoes i
    WHERE i.id = _termo AND i.sala_id = _sala FOR UPDATE;
  IF NOT FOUND OR documento IS NULL THEN RAISE EXCEPTION 'Termo não encontrado nesta sala. Atualize a lista'; END IF;
  PERFORM t.id FROM public.transferencias_bens_itens t
    WHERE t.transferencia_id = _termo ORDER BY t.id FOR UPDATE;
  IF EXISTS (
    SELECT 1 FROM public.transferencias_bens_itens t LEFT JOIN public.bens b ON b.id = t.bem_id
    WHERE t.transferencia_id = _termo AND t.estornado_em IS NULL AND (
      b.id IS NULL OR b.sala_id IS DISTINCT FROM t.destino_sala_id
      OR b.importacao_id IS DISTINCT FROM _termo
      OR (t.origem_sala_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.salas s WHERE s.id = t.origem_sala_id))
    )
  ) THEN
    RAISE EXCEPTION 'Não é possível excluir: um bem foi removido, movimentado para outro termo ou sua sala de origem não existe mais. Nenhum bem foi alterado';
  END IF;
  IF EXISTS (SELECT 1 FROM public.bens b WHERE b.importacao_id = _termo AND b.sala_id IS DISTINCT FROM _sala) THEN
    RAISE EXCEPTION 'Há bens vinculados a este termo em outra sala. Confira as movimentações antes de excluir';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.transferencias_bens_itens t JOIN public.bens b
      ON b.codigo_red = t.codigo_red AND b.sala_id IS NOT DISTINCT FROM t.origem_sala_id AND b.id <> t.bem_id
    WHERE t.transferencia_id = _termo AND t.estornado_em IS NULL
  ) THEN RAISE EXCEPTION 'A sala de origem já contém um dos códigos RED. Nenhum bem foi alterado'; END IF;
  UPDATE public.bens b SET sala_id = t.origem_sala_id,
    importacao_id = (SELECT i.id FROM public.importacoes i WHERE i.id = t.origem_importacao_id
      AND i.id <> _termo AND i.sala_id IS NOT DISTINCT FROM t.origem_sala_id),
    conferido = false, conferencia_finalizada = false
  FROM public.transferencias_bens_itens t
  WHERE t.transferencia_id = _termo AND t.estornado_em IS NULL AND b.id = t.bem_id;
  GET DIAGNOSTICS devolvidos = ROW_COUNT;
  UPDATE public.solicitacoes_bens SET ativa = false, updated_at = now()
    WHERE ativa AND bem_id IN (SELECT t.bem_id FROM public.transferencias_bens_itens t
      WHERE t.transferencia_id = _termo AND t.estornado_em IS NULL);
  UPDATE public.transferencias_bens_itens SET estornado_em = now(), estornado_por = auth.uid(), estorno_pedido = pedido
    WHERE transferencia_id = _termo AND estornado_em IS NULL;
  UPDATE public.bens SET importacao_id = NULL WHERE importacao_id = _termo;
  GET DIAGNOSTICS desvinculados = ROW_COUNT;
  DELETE FROM public.importacoes WHERE id = _termo AND sala_id = _sala;
  RETURN jsonb_build_object('devolvidos', devolvidos, 'desvinculados', desvinculados);
END;
$function$

CREATE OR REPLACE FUNCTION public.impedir_codigo_red_duplicado()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE chave text; local_existente text;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF public.chave_codigo_red_importacao(NEW.codigo_red) = public.chave_codigo_red_importacao(OLD.codigo_red)
      AND NEW.sala_id IS NOT DISTINCT FROM OLD.sala_id THEN RETURN NEW; END IF;
  END IF;
  chave := public.chave_codigo_red_importacao(NEW.codigo_red);
  IF chave IS NULL OR chave = '' THEN RAISE EXCEPTION 'Informe o código RED do bem'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('codigo-red:' || chave, 0));
  SELECT coalesce(s.nome, 'Sem sala') INTO local_existente FROM public.bens b
    LEFT JOIN public.salas s ON s.id = b.sala_id
    WHERE public.chave_codigo_red_importacao(b.codigo_red) = chave AND b.id <> NEW.id LIMIT 1;
  IF FOUND THEN
    RAISE EXCEPTION 'O código RED % já existe no local %. Use a importação com confirmação para mover o bem, sem duplicá-lo.', NEW.codigo_red, local_existente;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.importar_bens_html(_sala_id uuid, _arquivo text, _bens jsonb, _cabecalho jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  resultado jsonb;
  lote public.importacoes%ROWTYPE;
  local_atual public.salas%ROWTYPE;
  departamento_atual public.departamentos%ROWTYPE;
  nome_responsavel text;
  cpf_responsavel text;
  itens jsonb;
  ano integer;
BEGIN
  IF auth.uid() IS NULL OR NOT public.can_edit(auth.uid()) THEN
    RAISE EXCEPTION 'Sem permissão para importar';
  END IF;
  IF jsonb_typeof(_cabecalho) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'Cabeçalho do termo inválido';
  END IF;
  SELECT * INTO local_atual FROM public.salas WHERE id = _sala_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Local não encontrado'; END IF;
  SELECT * INTO departamento_atual FROM public.departamentos WHERE id = local_atual.departamento_id;
  SELECT p.nome, p.cpf INTO nome_responsavel, cpf_responsavel
    FROM public.user_salas us JOIN public.profiles p ON p.id = us.user_id
    WHERE us.sala_id = _sala_id ORDER BY p.created_at, p.id LIMIT 1;
  IF jsonb_typeof(_bens) IS DISTINCT FROM 'array' OR jsonb_array_length(_bens) = 0 THEN
    RAISE EXCEPTION 'Nenhum bem encontrado no HTML';
  END IF;
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(_bens) b
    WHERE jsonb_typeof(b) IS DISTINCT FROM 'object'
      OR NULLIF(trim(b->>'codigo_red'), '') IS NULL
      OR NULLIF(trim(b->>'descricao'), '') IS NULL
      OR jsonb_typeof(b->'valor') IS DISTINCT FROM 'number') THEN
    RAISE EXCEPTION 'O HTML contém dados de bens inválidos';
  END IF;
  SELECT jsonb_agg(jsonb_build_object('codigo_red', b.codigo_red, 'descricao', b.descricao,
      'valor', b.valor, 'incorporacao', b.incorporacao, 'tipo', b.tipo) ORDER BY b.codigo_red)
    INTO itens FROM (
      SELECT DISTINCT ON (x.codigo_red) x.* FROM jsonb_to_recordset(_bens)
        AS x(codigo_red text, descricao text, valor numeric, incorporacao text, tipo text)
      ORDER BY x.codigo_red
    ) b;
  resultado := public.importar_bens_pdf(_sala_id, _arquivo, itens);
  SELECT * INTO STRICT lote FROM public.importacoes WHERE numero = (resultado->>'numero')::bigint;
  ano := extract(year FROM lote.created_at AT TIME ZONE 'America/Sao_Paulo')::integer;
  UPDATE public.importacoes SET termo_ano = ano,
    termo_snapshot = jsonb_build_object(
      'local', local_atual.nome,
      'endereco', COALESCE(NULLIF(_cabecalho->>'endereco', ''), local_atual.endereco, ''),
      'historico', COALESCE(_cabecalho->>'historico', ''),
      'data_origem', COALESCE(_cabecalho->>'data', ''),
      'departamento', COALESCE(departamento_atual.departamento, ''),
      'diretor', COALESCE(departamento_atual.diretor, ''),
      'almoxarifado', COALESCE(departamento_atual.almoxarifado, ''),
      'endereco_departamento', COALESCE(departamento_atual.endereco, ''),
      'responsavel', COALESCE(NULLIF(nome_responsavel, ''), local_atual.responsavel, ''),
      'cpf', COALESCE(cpf_responsavel, ''),
      'bens', itens)
    WHERE id = lote.id;
  RETURN resultado || jsonb_build_object('importacao_id', lote.id, 'termo_numero', lote.numero::text || '/' || ano::text);
END;
$function$

CREATE OR REPLACE FUNCTION public.importar_bens_html_com_opcao(_sala_id uuid, _arquivo text, _bens jsonb, _cabecalho jsonb, _existentes jsonb, _gerar_termo boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  itens jsonb;
  atuais jsonb;
  esperados jsonb;
  chave text;
  novos integer := 0;
  movidos integer := 0;
BEGIN
  IF auth.uid() IS NULL OR NOT public.can_edit(auth.uid()) THEN
    RAISE EXCEPTION 'Sem permissão para importar';
  END IF;
  IF _gerar_termo IS NULL THEN RAISE EXCEPTION 'Escolha se deseja gerar um termo'; END IF;
  IF _gerar_termo THEN
    RETURN public.importar_bens_html_confirmado(_sala_id, _arquivo, _bens, _cabecalho, _existentes);
  END IF;
  IF jsonb_typeof(_bens) IS DISTINCT FROM 'array' OR jsonb_typeof(_existentes) IS DISTINCT FROM 'array'
    OR jsonb_typeof(_cabecalho) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'Dados da confirmação inválidos';
  END IF;
  IF jsonb_array_length(_bens) = 0 OR EXISTS (
    SELECT 1 FROM jsonb_array_elements(_bens) b WHERE jsonb_typeof(b) IS DISTINCT FROM 'object'
      OR nullif(public.chave_codigo_red_importacao(b->>'codigo_red'), '') IS NULL
      OR nullif(btrim(b->>'descricao'), '') IS NULL OR jsonb_typeof(b->'valor') IS DISTINCT FROM 'number'
  ) THEN RAISE EXCEPTION 'O HTML contém dados de bens inválidos'; END IF;
  SELECT jsonb_agg(item ORDER BY codigo) INTO itens FROM (
    SELECT DISTINCT ON (public.chave_codigo_red_importacao(b->>'codigo_red'))
      public.chave_codigo_red_importacao(b->>'codigo_red') AS codigo,
      b || jsonb_build_object('codigo_red', public.chave_codigo_red_importacao(b->>'codigo_red')) AS item
    FROM jsonb_array_elements(_bens) WITH ORDINALITY AS x(b, ordem)
    ORDER BY public.chave_codigo_red_importacao(b->>'codigo_red'), ordem
  ) t;
  FOR chave IN SELECT x->>'codigo_red' FROM jsonb_array_elements(itens) x ORDER BY x->>'codigo_red' LOOP
    PERFORM pg_advisory_xact_lock(hashtextextended('codigo-red:' || chave, 0));
  END LOOP;
  PERFORM s.id FROM public.salas s WHERE s.id = _sala_id OR s.id IN (
    SELECT b.sala_id FROM public.bens b WHERE public.chave_codigo_red_importacao(b.codigo_red) IN (
      SELECT x->>'codigo_red' FROM jsonb_array_elements(itens) x
    )
  ) ORDER BY s.id FOR UPDATE;
  IF NOT EXISTS (SELECT 1 FROM public.salas WHERE id = _sala_id) THEN RAISE EXCEPTION 'Local de destino não encontrado'; END IF;
  PERFORM b.id FROM public.bens b WHERE public.chave_codigo_red_importacao(b.codigo_red) IN (
    SELECT x->>'codigo_red' FROM jsonb_array_elements(itens) x
  ) ORDER BY b.id FOR UPDATE;
  SELECT coalesce(jsonb_agg(jsonb_build_object('id', b.id, 'sala_id', b.sala_id,
    'codigo_red', public.chave_codigo_red_importacao(b.codigo_red)) ORDER BY b.id), '[]'::jsonb)
    INTO atuais FROM public.bens b WHERE public.chave_codigo_red_importacao(b.codigo_red) IN (
      SELECT x->>'codigo_red' FROM jsonb_array_elements(itens) x
    );
  SELECT coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'sala_id', x.sala_id,
    'codigo_red', public.chave_codigo_red_importacao(x.codigo_red)) ORDER BY x.id), '[]'::jsonb)
    INTO esperados FROM jsonb_to_recordset(_existentes) AS x(id uuid, sala_id uuid, codigo_red text);
  IF atuais IS DISTINCT FROM esperados THEN
    RAISE EXCEPTION 'A localização de um dos bens mudou. Nenhum bem foi importado. Importe o arquivo novamente para conferir o aviso atualizado.';
  END IF;
  UPDATE public.solicitacoes_bens SET ativa = false, updated_at = now()
    WHERE ativa AND bem_id IN (
      SELECT b.id FROM public.bens b WHERE b.sala_id IS DISTINCT FROM _sala_id
        AND public.chave_codigo_red_importacao(b.codigo_red) IN (SELECT x->>'codigo_red' FROM jsonb_array_elements(itens) x)
    );
  UPDATE public.bens b SET sala_id = _sala_id, importacao_id = null, conferido = false, conferencia_finalizada = false
    WHERE b.sala_id IS DISTINCT FROM _sala_id
      AND public.chave_codigo_red_importacao(b.codigo_red) IN (SELECT x->>'codigo_red' FROM jsonb_array_elements(itens) x);
  GET DIAGNOSTICS movidos = ROW_COUNT;
  INSERT INTO public.bens(user_id, sala_id, codigo_red, descricao, valor, incorporacao, tipo)
    SELECT auth.uid(), _sala_id, x.codigo_red, x.descricao, x.valor, x.incorporacao, x.tipo
    FROM jsonb_to_recordset(itens) AS x(codigo_red text, descricao text, valor numeric, incorporacao text, tipo text)
    WHERE NOT EXISTS (SELECT 1 FROM public.bens b WHERE public.chave_codigo_red_importacao(b.codigo_red) = x.codigo_red);
  GET DIAGNOSTICS novos = ROW_COUNT;
  RETURN jsonb_build_object('importacao_id', null, 'numero', null, 'termo_numero', null,
    'novos', novos, 'repetidos', jsonb_array_length(itens) - novos, 'transferidos', movidos);
END;
$function$

CREATE OR REPLACE FUNCTION public.importar_bens_html_confirmado(_sala_id uuid, _arquivo text, _bens jsonb, _cabecalho jsonb, _existentes jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  itens jsonb; atuais jsonb; esperados jsonb; chave text; escolhido uuid;
  lote_id uuid; resultado jsonb; movidos integer := 0; removidos integer := 0; qtd integer;
BEGIN
  IF auth.uid() IS NULL OR NOT public.can_edit(auth.uid()) THEN RAISE EXCEPTION 'Sem permissão para importar'; END IF;
  IF jsonb_typeof(_bens) IS DISTINCT FROM 'array' OR jsonb_typeof(_existentes) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'Dados da confirmação inválidos';
  END IF;
  IF jsonb_array_length(_bens) = 0 OR EXISTS (
    SELECT 1 FROM jsonb_array_elements(_bens) b WHERE jsonb_typeof(b) IS DISTINCT FROM 'object'
      OR nullif(public.chave_codigo_red_importacao(b->>'codigo_red'), '') IS NULL
      OR nullif(btrim(b->>'descricao'), '') IS NULL OR jsonb_typeof(b->'valor') IS DISTINCT FROM 'number'
  ) THEN RAISE EXCEPTION 'O HTML contém dados de bens inválidos'; END IF;
  SELECT jsonb_agg(item ORDER BY codigo) INTO itens FROM (
    SELECT DISTINCT ON (public.chave_codigo_red_importacao(b->>'codigo_red'))
      public.chave_codigo_red_importacao(b->>'codigo_red') AS codigo,
      b || jsonb_build_object('codigo_red', public.chave_codigo_red_importacao(b->>'codigo_red')) AS item
    FROM jsonb_array_elements(_bens) WITH ORDINALITY AS x(b, ordem)
    ORDER BY public.chave_codigo_red_importacao(b->>'codigo_red'), ordem
  ) t;
  FOR chave IN SELECT x->>'codigo_red' FROM jsonb_array_elements(itens) x ORDER BY x->>'codigo_red' LOOP
    PERFORM pg_advisory_xact_lock(hashtextextended('codigo-red:' || chave, 0));
  END LOOP;
  PERFORM s.id FROM public.salas s WHERE s.id = _sala_id OR s.id IN (
    SELECT b.sala_id FROM public.bens b WHERE public.chave_codigo_red_importacao(b.codigo_red) IN (
      SELECT x->>'codigo_red' FROM jsonb_array_elements(itens) x
    )
  ) ORDER BY s.id FOR UPDATE;
  IF NOT EXISTS (SELECT 1 FROM public.salas WHERE id = _sala_id) THEN RAISE EXCEPTION 'Local de destino não encontrado'; END IF;
  PERFORM b.id FROM public.bens b WHERE public.chave_codigo_red_importacao(b.codigo_red) IN (
    SELECT x->>'codigo_red' FROM jsonb_array_elements(itens) x
  ) ORDER BY b.id FOR UPDATE;
  SELECT coalesce(jsonb_agg(jsonb_build_object('id', b.id, 'sala_id', b.sala_id,
    'codigo_red', public.chave_codigo_red_importacao(b.codigo_red)) ORDER BY b.id), '[]'::jsonb)
    INTO atuais FROM public.bens b WHERE public.chave_codigo_red_importacao(b.codigo_red) IN (
      SELECT x->>'codigo_red' FROM jsonb_array_elements(itens) x
    );
  SELECT coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'sala_id', x.sala_id,
    'codigo_red', public.chave_codigo_red_importacao(x.codigo_red)) ORDER BY x.id), '[]'::jsonb)
    INTO esperados FROM jsonb_to_recordset(_existentes) AS x(id uuid, sala_id uuid, codigo_red text);
  IF atuais IS DISTINCT FROM esperados THEN
    RAISE EXCEPTION 'A localização de um dos bens mudou. Nenhum bem foi importado. Importe o arquivo novamente para conferir o aviso atualizado.';
  END IF;
  FOR chave IN SELECT x->>'codigo_red' FROM jsonb_array_elements(itens) x ORDER BY x->>'codigo_red' LOOP
    SELECT b.id INTO escolhido FROM public.bens b WHERE public.chave_codigo_red_importacao(b.codigo_red) = chave
      ORDER BY (b.sala_id IS NOT DISTINCT FROM _sala_id) DESC, b.created_at, b.id LIMIT 1;
    IF escolhido IS NOT NULL THEN
      IF EXISTS (SELECT 1 FROM public.bens WHERE id = escolhido AND sala_id IS DISTINCT FROM _sala_id)
        OR EXISTS (SELECT 1 FROM public.bens WHERE public.chave_codigo_red_importacao(codigo_red) = chave AND sala_id IS DISTINCT FROM _sala_id) THEN
        movidos := movidos + 1;
      END IF;
      UPDATE public.solicitacoes_bens SET ativa = false, updated_at = now()
        WHERE ativa AND bem_id IN (SELECT b.id FROM public.bens b
          WHERE public.chave_codigo_red_importacao(b.codigo_red) = chave AND (b.id <> escolhido OR b.sala_id IS DISTINCT FROM _sala_id));
      DELETE FROM public.bens WHERE public.chave_codigo_red_importacao(codigo_red) = chave AND id <> escolhido;
      GET DIAGNOSTICS qtd = ROW_COUNT;
      removidos := removidos + qtd;
      UPDATE public.bens SET sala_id = _sala_id, importacao_id = null, conferido = false, conferencia_finalizada = false
        WHERE id = escolhido AND sala_id IS DISTINCT FROM _sala_id;
    END IF;
  END LOOP;
  resultado := public.importar_bens_html(_sala_id, _arquivo, itens, _cabecalho);
  lote_id := (resultado->>'importacao_id')::uuid;
  UPDATE public.bens b SET importacao_id = lote_id WHERE b.sala_id = _sala_id AND b.id IN (
    SELECT x.id FROM jsonb_to_recordset(_existentes) AS x(id uuid, sala_id uuid)
    WHERE x.sala_id IS DISTINCT FROM _sala_id
  );
  RETURN resultado || jsonb_build_object('transferidos', movidos, 'duplicatas_removidas', removidos);
END;
$function$

CREATE OR REPLACE FUNCTION public.importar_bens_html_multiplos_locais(_departamento_id uuid, _arquivo text, _locais jsonb, _gerar_termo boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  grupo jsonb;
  sala public.salas%ROWTYPE;
  destino uuid;
  chave text;
  nome_destino text;
  codigo_local text;
  resultado jsonb;
  resultados jsonb := '[]'::jsonb;
BEGIN
  IF auth.uid() IS NULL OR NOT public.can_edit(auth.uid()) THEN RAISE EXCEPTION 'Sem permissão para importar'; END IF;
  IF _gerar_termo IS NULL OR jsonb_typeof(_locais) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Dados da importação inválidos'; END IF;
  IF jsonb_array_length(_locais) < 2 THEN RAISE EXCEPTION 'Informe os locais físicos do HTML'; END IF;
  PERFORM id FROM public.departamentos WHERE id = _departamento_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Departamento não encontrado'; END IF;
  FOR grupo IN SELECT value FROM jsonb_array_elements(_locais) LOOP
    IF jsonb_typeof(grupo->'bens') IS DISTINCT FROM 'array'
      OR jsonb_typeof(grupo->'existentes') IS DISTINCT FROM 'array'
      OR jsonb_typeof(grupo->'cabecalho') IS DISTINCT FROM 'object'
      OR nullif(btrim(grupo->'cabecalho'->>'local'), '') IS NULL THEN
      RAISE EXCEPTION 'Um local físico não foi identificado corretamente';
    END IF;
    IF jsonb_array_length(grupo->'bens') = 0 THEN RAISE EXCEPTION 'Um local físico está sem bens'; END IF;
  END LOOP;
  IF EXISTS (
    SELECT public.chave_codigo_red_importacao(b->>'codigo_red')
    FROM jsonb_array_elements(_locais) g CROSS JOIN LATERAL jsonb_array_elements(g->'bens') b
    GROUP BY public.chave_codigo_red_importacao(b->>'codigo_red') HAVING count(*) > 1
  ) THEN RAISE EXCEPTION 'Há patrimônios repetidos entre os locais do HTML. Nada foi importado.'; END IF;
  IF EXISTS (
    SELECT coalesce(substring(g->'cabecalho'->>'local' FROM '^\d+'), lower(btrim(g->'cabecalho'->>'local')))
    FROM jsonb_array_elements(_locais) g GROUP BY 1 HAVING count(*) > 1
  ) THEN RAISE EXCEPTION 'Há locais físicos repetidos no pedido de importação'; END IF;
  FOR chave IN
    SELECT DISTINCT public.chave_codigo_red_importacao(b->>'codigo_red')
    FROM jsonb_array_elements(_locais) g CROSS JOIN LATERAL jsonb_array_elements(g->'bens') b ORDER BY 1
  LOOP
    PERFORM pg_advisory_xact_lock(hashtextextended('codigo-red:' || chave, 0));
  END LOOP;
  PERFORM s.id FROM public.salas s WHERE s.departamento_id = _departamento_id OR s.id IN (
    SELECT b.sala_id FROM public.bens b WHERE public.chave_codigo_red_importacao(b.codigo_red) IN (
      SELECT public.chave_codigo_red_importacao(x->>'codigo_red')
      FROM jsonb_array_elements(_locais) g CROSS JOIN LATERAL jsonb_array_elements(g->'bens') x
    )
  ) ORDER BY s.id FOR UPDATE;
  FOR grupo IN SELECT value FROM jsonb_array_elements(_locais) LOOP
    nome_destino := btrim(grupo->'cabecalho'->>'local');
    codigo_local := substring(nome_destino FROM '^\d+');
    destino := nullif(grupo->>'sala_id', '')::uuid;
    IF destino IS NULL THEN
      IF EXISTS (SELECT 1 FROM public.salas s WHERE s.departamento_id = _departamento_id AND (
        (codigo_local IS NOT NULL AND substring(s.nome FROM '^\d+') = codigo_local)
        OR lower(btrim(s.nome)) = lower(nome_destino)
      )) THEN RAISE EXCEPTION 'O cadastro dos locais mudou. Atualize a página e importe novamente; nada foi importado.'; END IF;
      INSERT INTO public.salas(user_id, departamento_id, nome, endereco, data_termo)
        VALUES (auth.uid(), _departamento_id, nome_destino, nullif(grupo->'cabecalho'->>'endereco', ''), nullif(grupo->'cabecalho'->>'data', ''))
        RETURNING * INTO sala;
      destino := sala.id;
    ELSE
      SELECT * INTO sala FROM public.salas WHERE id = destino AND departamento_id = _departamento_id;
      IF NOT FOUND THEN RAISE EXCEPTION 'Local físico não pertence ao departamento selecionado'; END IF;
      UPDATE public.salas SET nome = nome_destino,
        endereco = coalesce(nullif(sala.endereco, ''), nullif(grupo->'cabecalho'->>'endereco', '')),
        data_termo = coalesce(nullif(grupo->'cabecalho'->>'data', ''), sala.data_termo)
        WHERE id = destino RETURNING * INTO sala;
    END IF;
    resultado := public.importar_bens_html_com_opcao(destino, _arquivo, grupo->'bens', grupo->'cabecalho', grupo->'existentes', _gerar_termo);
    resultados := resultados || jsonb_build_array(resultado || jsonb_build_object('sala', to_jsonb(sala), 'quantidade', jsonb_array_length(grupo->'bens')));
  END LOOP;
  RETURN resultados;
END;
$function$

CREATE OR REPLACE FUNCTION public.importar_bens_pdf(_sala_id uuid, _arquivo text, _bens jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  lote public.importacoes%ROWTYPE;
  quantidade integer;
BEGIN
  IF auth.uid() IS NULL OR NOT public.can_edit(auth.uid()) THEN
    RAISE EXCEPTION 'Sem permissão para importar';
  END IF;
  PERFORM id FROM public.salas WHERE id = _sala_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Local não encontrado'; END IF;
  IF jsonb_typeof(_bens) IS DISTINCT FROM 'array' OR jsonb_array_length(_bens) = 0 THEN
    RAISE EXCEPTION 'Nenhum bem encontrado no PDF';
  END IF;
  INSERT INTO public.importacoes(sala_id, user_id, arquivo)
    VALUES (_sala_id, auth.uid(), _arquivo) RETURNING * INTO lote;
  INSERT INTO public.bens(user_id, sala_id, importacao_id, codigo_red, descricao, valor, incorporacao, tipo)
    SELECT auth.uid(), _sala_id, lote.id, public.chave_codigo_red_importacao(b.codigo_red), b.descricao, COALESCE(b.valor, 0), b.incorporacao, b.tipo
    FROM (
      SELECT DISTINCT ON (public.chave_codigo_red_importacao(x.codigo_red)) x.* FROM jsonb_to_recordset(_bens)
        AS x(codigo_red text, descricao text, valor numeric, incorporacao text, tipo text)
      WHERE x.codigo_red IS NOT NULL AND x.descricao IS NOT NULL
      ORDER BY public.chave_codigo_red_importacao(x.codigo_red)
    ) b
    WHERE NOT EXISTS (SELECT 1 FROM public.bens e WHERE e.sala_id = _sala_id
      AND public.chave_codigo_red_importacao(e.codigo_red) = public.chave_codigo_red_importacao(b.codigo_red));
  GET DIAGNOSTICS quantidade = ROW_COUNT;
  RETURN jsonb_build_object('numero', lote.numero, 'novos', quantidade, 'repetidos', jsonb_array_length(_bens) - quantidade);
END;
$function$

CREATE OR REPLACE FUNCTION public.incluir_bens_fornecedor(_itens jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE n integer;
BEGIN
  IF auth.uid() IS NULL OR NOT public.can_edit(auth.uid()) THEN
    RAISE EXCEPTION 'Sem permissão para incluir bens';
  END IF;
  INSERT INTO public.bens(user_id, sala_id, codigo_red, descricao, ano_pedido, pedido, ano_empenho, empenho, nota_fiscal, fornecedor)
  SELECT DISTINCT ON (ltrim(x.codigo_red,'0')) auth.uid(), NULL, x.codigo_red, coalesce(nullif(btrim(x.descricao),''),'Sem descrição'),
    nullif(x.ano_pedido,''), nullif(x.pedido,''), nullif(x.ano_empenho,''), nullif(x.empenho,''), nullif(x.nota_fiscal,''), nullif(x.fornecedor,'')
  FROM jsonb_to_recordset(_itens) AS x(codigo_red text, descricao text, ano_pedido text, pedido text, ano_empenho text, empenho text, nota_fiscal text, fornecedor text)
  WHERE nullif(btrim(x.codigo_red),'') IS NOT NULL
    AND NOT EXISTS (SELECT 1 FROM public.bens b WHERE ltrim(b.codigo_red,'0') = ltrim(x.codigo_red,'0'));
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END $function$

CREATE OR REPLACE FUNCTION public.incluir_bens_no_termo(_termo uuid, _sala uuid, _itens uuid[], _aceitar_repetidos boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  documento jsonb;
  novos jsonb;
  quantidade integer;
  conflito jsonb;
BEGIN
  IF auth.uid() IS NULL OR NOT public.can_edit(auth.uid()) THEN
    RAISE EXCEPTION 'Sem permissão para incluir bens em termos';
  END IF;
  quantidade := coalesce(cardinality(_itens), 0);
  IF quantidade < 1 OR quantidade > 500 OR (SELECT count(DISTINCT x) FROM unnest(_itens) x) <> quantidade THEN
    RAISE EXCEPTION 'Selecione de 1 a 500 bens diferentes';
  END IF;
  PERFORM s.id FROM public.salas s WHERE s.id = _sala FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Sala não encontrada'; END IF;
  PERFORM b.id FROM public.bens b WHERE b.id = ANY(_itens) ORDER BY b.id FOR UPDATE;
  SELECT i.termo_snapshot INTO documento FROM public.importacoes i
    WHERE i.id = _termo AND i.sala_id = _sala FOR UPDATE;
  IF NOT FOUND OR documento IS NULL OR jsonb_typeof(documento) <> 'object'
    OR jsonb_typeof(documento->'bens') IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'O termo não possui documento válido nesta sala';
  END IF;
  IF jsonb_array_length(documento->'bens') = 0 THEN
    RAISE EXCEPTION 'Os dados deste termo não estão disponíveis';
  END IF;
  IF (SELECT count(*) FROM public.bens b WHERE b.id = ANY(_itens) AND b.sala_id = _sala) <> quantidade THEN
    RAISE EXCEPTION 'Um dos bens foi removido ou mudou de sala. Atualize a busca antes de incluir';
  END IF;
  conflito := public.bem_em_outro_termo_da_sala(_sala, _itens, _termo);
  IF conflito IS NOT NULL AND NOT coalesce(_aceitar_repetidos, false) THEN
    RAISE EXCEPTION 'O bem % já está no termo % desta sala. Um bem só pode estar em outro termo da mesma sala se tiver ido para outra sala e retornado depois', conflito->>'codigo_red', conflito->>'termo';
  END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'codigo_red', b.codigo_red, 'descricao', b.descricao, 'valor', b.valor,
    'incorporacao', b.incorporacao, 'tipo', b.tipo
  ) ORDER BY b.codigo_red), '[]'::jsonb) INTO novos
    FROM public.bens b WHERE b.id = ANY(_itens)
    AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(documento->'bens') item
      WHERE item->>'codigo_red' = b.codigo_red);
  UPDATE public.importacoes SET termo_snapshot = jsonb_set(documento, '{bens}', (documento->'bens') || novos)
    WHERE id = _termo AND sala_id = _sala;
  UPDATE public.bens SET importacao_id = _termo
    WHERE id = ANY(_itens) AND sala_id = _sala AND importacao_id IS DISTINCT FROM _termo;
  RETURN jsonb_build_object('quantidade', quantidade);
END;
$function$

