CREATE OR REPLACE FUNCTION public.numerar_recebimento_veiculo()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE existente public.recebimentos_veiculos%ROWTYPE;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    NEW.numero := OLD.numero;
    NEW.ano := OLD.ano;
    NEW.criado_em := OLD.criado_em;
    RETURN NEW;
  END IF;
  SELECT * INTO existente FROM public.recebimentos_veiculos WHERE bem_id = NEW.bem_id;
  IF FOUND THEN
    NEW.numero := existente.numero;
    NEW.ano := existente.ano;
    NEW.criado_em := existente.criado_em;
    RETURN NEW;
  END IF;
  NEW.ano := extract(year FROM now() AT TIME ZONE 'America/Sao_Paulo')::integer;
  NEW.criado_em := now();
  UPDATE public.termos_numeracao_contador SET ultimo_numero = ultimo_numero + 1
    WHERE id = true RETURNING ultimo_numero INTO NEW.numero;
  IF NOT FOUND THEN RAISE EXCEPTION 'Numeração indisponível'; END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.pesquisar_bens_salas(_termo text)
 RETURNS TABLE(bem jsonb, local_nome text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
DECLARE
  uid uuid := auth.uid();
  todas boolean;
  permitidas uuid[];
  termo text := public.normalizar_texto_pesquisa_bens(_termo);
  numeros text := replace(regexp_replace(coalesce(_termo, ''), '[[:space:]' || chr(160) || ']+', '', 'g'), '.', '');
  codigos text[];
  palavras text[];
  padroes text[];
BEGIN
  IF uid IS NULL OR termo = '' THEN RETURN; END IF;
  -- Mesmas regras de acesso das salas, verificadas uma única vez por pesquisa.
  todas := public.can_edit(uid);
  IF NOT todas THEN
    SELECT coalesce(array_agg(sala_id), ARRAY[]::uuid[]) INTO permitidas FROM public.user_salas WHERE user_id = uid;
    IF cardinality(permitidas) = 0 THEN RETURN; END IF;
  END IF;

  IF numeros ~ '^[0-9]+(,[0-9]+)+,?$' THEN
    codigos := string_to_array(rtrim(numeros, ','), ',');
    RETURN QUERY SELECT to_jsonb(b), s.nome FROM public.bens b JOIN public.salas s ON s.id = b.sala_id
      WHERE replace(b.codigo_red, '.', '') = ANY(codigos) AND (todas OR b.sala_id = ANY(permitidas))
      ORDER BY b.codigo_red, b.id;
    RETURN;
  END IF;
  IF numeros ~ '^[0-9]+$' THEN
    RETURN QUERY SELECT to_jsonb(b), s.nome FROM public.bens b JOIN public.salas s ON s.id = b.sala_id
      WHERE replace(b.codigo_red, '.', '') = numeros AND (todas OR b.sala_id = ANY(permitidas))
      ORDER BY b.id;
    IF FOUND THEN RETURN; END IF;
    RETURN QUERY SELECT to_jsonb(b), s.nome FROM public.bens b JOIN public.salas s ON s.id = b.sala_id
      WHERE replace(b.codigo_red, '.', '') LIKE '%' || numeros || '%' AND (todas OR b.sala_id = ANY(permitidas))
      ORDER BY b.codigo_red, b.id;
    RETURN;
  END IF;

  palavras := array_remove(regexp_split_to_array(btrim(regexp_replace(termo, '[^[:alnum:]]+', ' ', 'g')), ' +'), '');
  IF termo ~ '[[:alpha:]]' AND cardinality(palavras) > 0 THEN
    SELECT array_agg('%' || p || '%') INTO padroes FROM unnest(palavras) p;
    RETURN QUERY SELECT to_jsonb(b), s.nome FROM public.bens b JOIN public.salas s ON s.id = b.sala_id
      WHERE (todas OR b.sala_id = ANY(permitidas)) AND (
        (public.normalizar_texto_pesquisa_bens(b.descricao) LIKE padroes[1]
          AND public.normalizar_texto_pesquisa_bens(b.descricao) LIKE ALL (padroes))
        OR replace(b.codigo_red, '.', '') LIKE '%' || upper(numeros) || '%'
        OR replace(b.codigo_red, '.', '') LIKE '%' || numeros || '%')
      ORDER BY b.codigo_red, b.id;
    RETURN;
  END IF;

  -- Valores em reais (ex.: 1.250,75 ou R$ 1.250,75).
  RETURN QUERY SELECT to_jsonb(b), s.nome FROM public.bens b JOIN public.salas s ON s.id = b.sala_id
    WHERE (todas OR b.sala_id = ANY(permitidas)) AND (
      strpos(replace(b.valor::text, '.', ','), termo) > 0
      OR strpos(b.valor::text, termo) > 0
      OR strpos('r$ ' || translate(to_char(b.valor, 'FM999,999,999,990.00'), ',.', '.,'), termo) > 0)
    ORDER BY b.codigo_red, b.id;
END;
$function$

CREATE OR REPLACE FUNCTION public.registrar_item_transferido()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  lote public.importacoes%ROWTYPE;
BEGIN
  SELECT * INTO lote FROM public.importacoes WHERE id = NEW.importacao_id AND arquivo = 'Transferência de bens';
  IF FOUND THEN
    INSERT INTO public.transferencias_bens_itens (
      transferencia_id, numero, termo_ano, bem_id, codigo_red, descricao, valor,
      origem_sala_id, origem_nome, origem_importacao_id, destino_sala_id, destino_nome
    ) VALUES (
      lote.id, lote.numero, lote.termo_ano, NEW.id, NEW.codigo_red, NEW.descricao, NEW.valor,
      OLD.sala_id, coalesce((SELECT nome FROM public.salas WHERE id = OLD.sala_id), 'Sem sala'), OLD.importacao_id,
      NEW.sala_id, coalesce((SELECT nome FROM public.salas WHERE id = NEW.sala_id), 'Sala removida')
    ) ON CONFLICT (transferencia_id, bem_id) DO NOTHING;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.salvar_conferencia(_sala_id uuid, _bens_ids uuid[], _localizados uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NULL OR NOT public.pode_ver_sala(auth.uid(), _sala_id) THEN
    RAISE EXCEPTION 'Sem permissão para salvar a conferência deste local.';
  END IF;
  IF _bens_ids IS NULL OR _localizados IS NULL OR cardinality(_bens_ids) = 0 THEN
    RAISE EXCEPTION 'Nenhum bem informado para conferência.';
  END IF;
  IF EXISTS (
    SELECT 1 FROM unnest(_bens_ids) AS item(id)
    WHERE NOT EXISTS (SELECT 1 FROM public.bens b WHERE b.id = item.id AND b.sala_id = _sala_id)
  ) OR EXISTS (
    SELECT 1 FROM unnest(_localizados) AS item(id)
    WHERE item.id IS NULL OR NOT (item.id = ANY(_bens_ids))
  ) THEN
    RAISE EXCEPTION 'A lista de bens mudou. Recarregue o local antes de salvar.';
  END IF;
  UPDATE public.bens
  SET conferido = (id = ANY(_localizados)), conferencia_finalizada = true
  WHERE sala_id = _sala_id AND id = ANY(_bens_ids);
END;
$function$

CREATE OR REPLACE FUNCTION public.salvar_observacao_solicitacao(_bem_id uuid, _obs text, _tipo text, _destino text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _bem public.bens%ROWTYPE; _origem text;
BEGIN
 SELECT * INTO _bem FROM public.bens WHERE id = _bem_id FOR UPDATE;
 IF NOT FOUND OR auth.uid() IS NULL OR NOT public.pode_ver_sala(auth.uid(), _bem.sala_id) THEN
  RAISE EXCEPTION 'Você não tem permissão para editar este bem.';
 END IF;
 IF _tipo IS NOT NULL AND _tipo NOT IN ('transferencia', 'inservivel') THEN
  RAISE EXCEPTION 'Opção inválida.';
 END IF;
 IF length(coalesce(_obs, '')) > 2000 THEN RAISE EXCEPTION 'Use até 2000 caracteres na observação.'; END IF;
 IF _tipo = 'transferencia' AND (length(btrim(coalesce(_destino, ''))) < 1 OR length(btrim(_destino)) > 300) THEN
  RAISE EXCEPTION 'Informe o local de destino com até 300 caracteres.';
 END IF;
 UPDATE public.bens SET observacao = coalesce(_obs, '') WHERE id = _bem_id;
 IF _tipo IS NULL THEN
  UPDATE public.solicitacoes_bens SET ativa = false, updated_at = clock_timestamp() WHERE bem_id = _bem_id AND ativa;
  RETURN;
 END IF;
 SELECT nome INTO _origem FROM public.salas WHERE id = _bem.sala_id;
 INSERT INTO public.solicitacoes_bens (bem_id, sala_id, user_id, tipo, destino, observacao, codigo_red, descricao, valor, local_origem)
 VALUES (_bem.id, _bem.sala_id, auth.uid(), _tipo, CASE WHEN _tipo = 'transferencia' THEN btrim(_destino) ELSE NULL END, coalesce(_obs, ''), _bem.codigo_red, _bem.descricao, _bem.valor, coalesce(_origem, 'Local removido'))
 ON CONFLICT (bem_id) DO UPDATE SET sala_id = EXCLUDED.sala_id, user_id = EXCLUDED.user_id, tipo = EXCLUDED.tipo, destino = EXCLUDED.destino, observacao = EXCLUDED.observacao, codigo_red = EXCLUDED.codigo_red, descricao = EXCLUDED.descricao, valor = EXCLUDED.valor, local_origem = EXCLUDED.local_origem, ativa = true, updated_at = clock_timestamp()
 WHERE (solicitacoes_bens.tipo, solicitacoes_bens.destino, solicitacoes_bens.observacao, solicitacoes_bens.codigo_red, solicitacoes_bens.descricao, solicitacoes_bens.valor, solicitacoes_bens.local_origem, solicitacoes_bens.ativa)
 IS DISTINCT FROM (EXCLUDED.tipo, EXCLUDED.destino, EXCLUDED.observacao, EXCLUDED.codigo_red, EXCLUDED.descricao, EXCLUDED.valor, EXCLUDED.local_origem, true);
END;
$function$

CREATE OR REPLACE FUNCTION public.salvar_recebimento_termo(_importacao_id uuid, _recebedor text, _cpf text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _entregador text;
  _snapshot jsonb;
  _sala_id uuid;
  _responsavel jsonb;
  _cpf_limpo text := regexp_replace(coalesce(_cpf, ''), '[^0-9]', '', 'g');
BEGIN
  IF auth.uid() IS NULL OR NOT public.can_edit(auth.uid()) THEN
    RAISE EXCEPTION 'Você não tem permissão para registrar o recebimento.';
  END IF;
  IF length(btrim(coalesce(_recebedor, ''))) < 2 OR length(btrim(_recebedor)) > 200 OR length(_cpf_limpo) <> 11 THEN
    RAISE EXCEPTION 'Informe o responsável pelo recebimento e um CPF com 11 dígitos.';
  END IF;
  SELECT coalesce(nullif(btrim(nome), ''), nullif(btrim(login), ''), nullif(btrim(email), ''))
    INTO _entregador FROM public.profiles WHERE id = auth.uid();
  _entregador := coalesce(_entregador, nullif(auth.jwt()->'user_metadata'->>'nome', ''), nullif(auth.jwt()->'user_metadata'->>'full_name', ''), nullif(auth.jwt()->>'email', ''));
  IF _entregador IS NULL THEN
    RAISE EXCEPTION 'Complete o nome do seu usuário antes de imprimir o termo.';
  END IF;
  SELECT termo_snapshot, sala_id INTO _snapshot, _sala_id FROM public.importacoes WHERE id = _importacao_id FOR UPDATE;
  IF _snapshot IS NULL OR jsonb_typeof(_snapshot) <> 'object' THEN
    RAISE EXCEPTION 'Os dados desta importação não estão disponíveis.';
  END IF;
  _responsavel := public.dados_responsavel_sala_termo(_sala_id);
  _snapshot := _snapshot || _responsavel || jsonb_build_object(
    'responsavel_recebimento', btrim(_recebedor), 'cpf_recebimento', _cpf_limpo,
    'entregador', _entregador, 'entregador_id', auth.uid(),
    'data_termo', to_char(timezone('America/Sao_Paulo', now()), 'DD/MM/YYYY'));
  UPDATE public.importacoes SET termo_snapshot = _snapshot WHERE id = _importacao_id;
  RETURN _snapshot;
END;
$function$

CREATE OR REPLACE FUNCTION public.sincronizar_status_bem()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.status := CASE WHEN NEW.conferido THEN 'LOCALIZADO' ELSE 'NÃO LOCALIZADO' END;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.transferir_bens(_destino uuid, _itens jsonb, _pedido uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  destino public.salas%ROWTYPE;
  dept public.departamentos%ROWTYPE;
  lote public.importacoes%ROWTYPE;
  quantidade integer;
  nome_responsavel text;
  cpf_responsavel text;
  snapshot_itens jsonb;
  origens text;
BEGIN
  IF auth.uid() IS NULL OR NOT public.can_edit(auth.uid()) THEN RAISE EXCEPTION 'Sem permissão para transferir bens'; END IF;
  IF _pedido IS NULL OR _destino IS NULL THEN RAISE EXCEPTION 'Informe o local de destino'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(_pedido::text, 0));
  SELECT * INTO lote FROM public.importacoes WHERE id = _pedido;
  IF FOUND THEN
    IF lote.user_id <> auth.uid() OR lote.sala_id <> _destino OR lote.arquivo NOT LIKE 'Transferência %' THEN RAISE EXCEPTION 'Pedido inválido'; END IF;
    RETURN to_jsonb(lote);
  END IF;
  IF jsonb_typeof(_itens) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Selecione os bens para transferir'; END IF;
  quantidade := jsonb_array_length(_itens);
  IF quantidade < 1 OR quantidade > 500 THEN RAISE EXCEPTION 'Selecione de 1 a 500 bens por transferência'; END IF;
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(_itens) x WHERE jsonb_typeof(x) IS DISTINCT FROM 'object' OR x->>'id' IS NULL OR NOT (x ? 'sala_id')) THEN RAISE EXCEPTION 'Lista de bens inválida'; END IF;
  IF (SELECT count(DISTINCT x.id) FROM jsonb_to_recordset(_itens) AS x(id uuid, sala_id uuid)) <> quantidade THEN RAISE EXCEPTION 'Existem bens repetidos na seleção'; END IF;
  PERFORM s.id FROM public.salas s WHERE s.id = _destino OR s.id IN (SELECT x.sala_id FROM jsonb_to_recordset(_itens) AS x(id uuid, sala_id uuid)) ORDER BY s.id FOR UPDATE;
  SELECT * INTO destino FROM public.salas WHERE id = _destino;
  IF NOT FOUND THEN RAISE EXCEPTION 'Local de destino não encontrado'; END IF;
  PERFORM b.id FROM public.bens b JOIN jsonb_to_recordset(_itens) AS x(id uuid, sala_id uuid) ON x.id=b.id ORDER BY b.id FOR UPDATE OF b;
  IF (SELECT count(*) FROM public.bens b JOIN jsonb_to_recordset(_itens) AS x(id uuid, sala_id uuid) ON x.id=b.id AND b.sala_id IS NOT DISTINCT FROM x.sala_id WHERE b.sala_id IS DISTINCT FROM _destino) <> quantidade THEN
    RAISE EXCEPTION 'Um bem foi removido, mudou de sala ou já está no destino. Filtre novamente antes de salvar';
  END IF;
  IF EXISTS (SELECT 1 FROM public.bens b JOIN jsonb_to_recordset(_itens) AS x(id uuid, sala_id uuid) ON x.id=b.id GROUP BY b.codigo_red HAVING count(*) > 1) THEN RAISE EXCEPTION 'Há códigos RED repetidos na seleção. Confira os locais de origem'; END IF;
  IF EXISTS (SELECT 1 FROM public.bens d JOIN public.bens b ON b.codigo_red=d.codigo_red JOIN jsonb_to_recordset(_itens) AS x(id uuid, sala_id uuid) ON x.id=b.id WHERE d.sala_id=_destino) THEN RAISE EXCEPTION 'O destino já contém um dos códigos RED selecionados'; END IF;
  SELECT * INTO dept FROM public.departamentos WHERE id=destino.departamento_id;
  SELECT p.nome,p.cpf INTO nome_responsavel,cpf_responsavel FROM public.user_salas us JOIN public.profiles p ON p.id=us.user_id WHERE us.sala_id=_destino AND p.nome IS NOT NULL ORDER BY p.created_at DESC,p.id LIMIT 1;
  SELECT jsonb_agg(jsonb_build_object('codigo_red',b.codigo_red,'descricao',b.descricao,'valor',b.valor,'incorporacao',b.incorporacao,'tipo',b.tipo) ORDER BY b.codigo_red), string_agg(DISTINCT coalesce(s.nome,'Sem sala'),', ' ORDER BY coalesce(s.nome,'Sem sala')) INTO snapshot_itens,origens FROM public.bens b JOIN jsonb_to_recordset(_itens) AS x(id uuid, sala_id uuid) ON x.id=b.id LEFT JOIN public.salas s ON s.id=b.sala_id;
  INSERT INTO public.importacoes(id,sala_id,user_id,arquivo,termo_ano,termo_snapshot) VALUES (_pedido,_destino,auth.uid(),'Transferência de bens',extract(year from timezone('America/Sao_Paulo',now()))::integer,
    jsonb_build_object('local',destino.nome,'endereco',coalesce(destino.endereco,''),'historico','Transferência de '||quantidade||' bem(ns). Origem: '||origens||'. Destino: '||destino.nome||'.','data_origem',to_char(timezone('America/Sao_Paulo',now()),'DD/MM/YYYY'),'departamento',coalesce(dept.departamento,''),'diretor',coalesce(dept.diretor,''),'almoxarifado',coalesce(dept.almoxarifado,''),'endereco_departamento',coalesce(dept.endereco,''),'responsavel',coalesce(nome_responsavel,destino.responsavel,''),'cpf',coalesce(cpf_responsavel,''),'bens',snapshot_itens)) RETURNING * INTO lote;
  UPDATE public.bens b SET sala_id=_destino,importacao_id=lote.id,conferido=false,conferencia_finalizada=false FROM jsonb_to_recordset(_itens) AS x(id uuid, sala_id uuid) WHERE b.id=x.id;
  UPDATE public.solicitacoes_bens s SET ativa=false,updated_at=now() WHERE s.ativa AND s.bem_id IN (SELECT x.id FROM jsonb_to_recordset(_itens) AS x(id uuid, sala_id uuid));
  RETURN to_jsonb(lote);
END;
$function$

CREATE OR REPLACE FUNCTION public.transferir_bens(_destino uuid, _itens jsonb, _pedido uuid, _aceitar_repetidos boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  destino public.salas%ROWTYPE;
  dept public.departamentos%ROWTYPE;
  lote public.importacoes%ROWTYPE;
  quantidade integer;
  nome_responsavel text;
  cpf_responsavel text;
  snapshot_itens jsonb;
  origens text;
BEGIN
  IF auth.uid() IS NULL OR NOT public.can_edit(auth.uid()) THEN RAISE EXCEPTION 'Sem permissão para transferir bens'; END IF;
  IF _pedido IS NULL OR _destino IS NULL THEN RAISE EXCEPTION 'Informe o local de destino'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(_pedido::text, 0));
  SELECT * INTO lote FROM public.importacoes WHERE id = _pedido;
  IF FOUND THEN
    IF lote.user_id <> auth.uid() OR lote.sala_id <> _destino OR lote.arquivo NOT LIKE 'Transferência %' THEN RAISE EXCEPTION 'Pedido inválido'; END IF;
    RETURN to_jsonb(lote);
  END IF;
  IF jsonb_typeof(_itens) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Selecione os bens para transferir'; END IF;
  quantidade := jsonb_array_length(_itens);
  IF quantidade < 1 OR quantidade > 500 THEN RAISE EXCEPTION 'Selecione de 1 a 500 bens por transferência'; END IF;
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(_itens) x WHERE jsonb_typeof(x) IS DISTINCT FROM 'object' OR x->>'id' IS NULL OR NOT (x ? 'sala_id')) THEN RAISE EXCEPTION 'Lista de bens inválida'; END IF;
  IF (SELECT count(DISTINCT x.id) FROM jsonb_to_recordset(_itens) AS x(id uuid, sala_id uuid)) <> quantidade THEN RAISE EXCEPTION 'Existem bens repetidos na seleção'; END IF;
  PERFORM s.id FROM public.salas s WHERE s.id = _destino OR s.id IN (SELECT x.sala_id FROM jsonb_to_recordset(_itens) AS x(id uuid, sala_id uuid)) ORDER BY s.id FOR UPDATE;
  SELECT * INTO destino FROM public.salas WHERE id = _destino;
  IF NOT FOUND THEN RAISE EXCEPTION 'Local de destino não encontrado'; END IF;
  PERFORM b.id FROM public.bens b JOIN jsonb_to_recordset(_itens) AS x(id uuid, sala_id uuid) ON x.id=b.id ORDER BY b.id FOR UPDATE OF b;
  IF (SELECT count(*) FROM public.bens b JOIN jsonb_to_recordset(_itens) AS x(id uuid, sala_id uuid) ON x.id=b.id AND b.sala_id IS NOT DISTINCT FROM x.sala_id WHERE (b.sala_id IS DISTINCT FROM _destino OR coalesce(_aceitar_repetidos, false))) <> quantidade THEN
    RAISE EXCEPTION 'Um bem foi removido, mudou de sala ou já está no destino. Filtre novamente antes de salvar';
  END IF;
  IF EXISTS (SELECT 1 FROM public.bens b JOIN jsonb_to_recordset(_itens) AS x(id uuid, sala_id uuid) ON x.id=b.id GROUP BY b.codigo_red HAVING count(*) > 1) THEN RAISE EXCEPTION 'Há códigos RED repetidos na seleção. Confira os locais de origem'; END IF;
  IF EXISTS (SELECT 1 FROM public.bens d JOIN public.bens b ON b.codigo_red=d.codigo_red JOIN jsonb_to_recordset(_itens) AS x(id uuid, sala_id uuid) ON x.id=b.id WHERE d.sala_id=_destino AND d.id <> b.id) THEN RAISE EXCEPTION 'O destino já contém um dos códigos RED selecionados'; END IF;
  IF NOT coalesce(_aceitar_repetidos, false) AND public.bem_em_outro_termo_da_sala(_destino, ARRAY(SELECT x.id FROM jsonb_to_recordset(_itens) AS x(id uuid, sala_id uuid)), _pedido) IS NOT NULL THEN RAISE EXCEPTION 'Um dos bens já consta em outro termo desta sala. Clique em Aceitar bens em termos diferentes para autorizar'; END IF;
  SELECT * INTO dept FROM public.departamentos WHERE id=destino.departamento_id;
  SELECT p.nome,p.cpf INTO nome_responsavel,cpf_responsavel FROM public.user_salas us JOIN public.profiles p ON p.id=us.user_id WHERE us.sala_id=_destino AND p.nome IS NOT NULL ORDER BY p.created_at DESC,p.id LIMIT 1;
  SELECT jsonb_agg(jsonb_build_object('codigo_red',b.codigo_red,'descricao',b.descricao,'valor',b.valor,'incorporacao',b.incorporacao,'tipo',b.tipo) ORDER BY b.codigo_red), string_agg(DISTINCT coalesce(s.nome,'Sem sala'),', ' ORDER BY coalesce(s.nome,'Sem sala')) INTO snapshot_itens,origens FROM public.bens b JOIN jsonb_to_recordset(_itens) AS x(id uuid, sala_id uuid) ON x.id=b.id LEFT JOIN public.salas s ON s.id=b.sala_id;
  INSERT INTO public.importacoes(id,sala_id,user_id,arquivo,termo_ano,termo_snapshot) VALUES (_pedido,_destino,auth.uid(),'Transferência de bens',extract(year from timezone('America/Sao_Paulo',now()))::integer,
    jsonb_build_object('local',destino.nome,'endereco',coalesce(destino.endereco,''),'historico','Transferência de '||quantidade||' bem(ns). Origem: '||origens||'. Destino: '||destino.nome||'.','data_origem',to_char(timezone('America/Sao_Paulo',now()),'DD/MM/YYYY'),'departamento',coalesce(dept.departamento,''),'diretor',coalesce(dept.diretor,''),'almoxarifado',coalesce(dept.almoxarifado,''),'endereco_departamento',coalesce(dept.endereco,''),'responsavel',coalesce(nome_responsavel,destino.responsavel,''),'cpf',coalesce(cpf_responsavel,''),'bens',snapshot_itens)) RETURNING * INTO lote;
  UPDATE public.bens b SET sala_id=_destino,importacao_id=lote.id,conferido=false,conferencia_finalizada=false FROM jsonb_to_recordset(_itens) AS x(id uuid, sala_id uuid) WHERE b.id=x.id;
  UPDATE public.solicitacoes_bens s SET ativa=false,updated_at=now() WHERE s.ativa AND s.bem_id IN (SELECT x.id FROM jsonb_to_recordset(_itens) AS x(id uuid, sala_id uuid));
  RETURN to_jsonb(lote);
END;
$function$

CREATE OR REPLACE FUNCTION public.unificar_termos(_sala uuid, _termos uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  destino public.importacoes%ROWTYPE;
  origem public.importacoes%ROWTYPE;
  itens jsonb;
  ids uuid[];
  movidos integer := 0;
BEGIN
  IF auth.uid() IS NULL OR NOT public.can_edit(auth.uid()) THEN
    RAISE EXCEPTION 'Sem permissão para unificar termos';
  END IF;
  IF _sala IS NULL OR coalesce(cardinality(_termos), 0) <> 2 OR _termos[1] IS NULL OR _termos[2] IS NULL OR _termos[1] = _termos[2] THEN
    RAISE EXCEPTION 'Selecione exatamente dois termos diferentes';
  END IF;
  IF NOT public.pode_ver_sala(auth.uid(), _sala) THEN RAISE EXCEPTION 'Sala indisponível para sua conta'; END IF;
  PERFORM s.id FROM public.salas s WHERE s.id = _sala FOR UPDATE;
  PERFORM b.id FROM public.bens b WHERE b.sala_id = _sala OR b.importacao_id = ANY(_termos) ORDER BY b.id FOR UPDATE;
  PERFORM i.id FROM public.importacoes i WHERE i.id = ANY(_termos) ORDER BY i.id FOR UPDATE;
  IF (SELECT count(*) FROM public.importacoes i WHERE i.id = ANY(_termos) AND i.sala_id = _sala
      AND jsonb_typeof(i.termo_snapshot) = 'object' AND jsonb_typeof(i.termo_snapshot->'bens') = 'array') <> 2 THEN
    RAISE EXCEPTION 'Os dois termos precisam pertencer a esta sala. Atualize a lista';
  END IF;
  SELECT * INTO destino FROM public.importacoes WHERE id = ANY(_termos) ORDER BY numero DESC LIMIT 1;
  SELECT * INTO origem FROM public.importacoes WHERE id = ANY(_termos) AND id <> destino.id;
  IF EXISTS (SELECT 1 FROM public.bens b WHERE b.importacao_id = origem.id AND b.sala_id IS DISTINCT FROM _sala) THEN
    RAISE EXCEPTION 'O termo % tem bens em outra sala. Confira as movimentações antes de unificar', lpad(origem.numero::text, 5, '0');
  END IF;
  SELECT coalesce(array_agg(b.id ORDER BY b.id), ARRAY[]::uuid[]) INTO ids
  FROM public.bens b WHERE b.sala_id = _sala AND (
    b.importacao_id = ANY(_termos) OR EXISTS (
      SELECT 1 FROM public.importacoes i
      CROSS JOIN LATERAL jsonb_array_elements_text(CASE WHEN jsonb_typeof(i.termo_snapshot->'bem_ids') = 'array' THEN i.termo_snapshot->'bem_ids' ELSE '[]'::jsonb END) x(id)
      WHERE i.id = ANY(_termos) AND i.termo_snapshot->>'tipo_documento' = 'novo_termo' AND x.id = b.id::text
    )
  );
  SELECT coalesce(jsonb_agg(escolhidos.item ORDER BY escolhidos.chave), '[]'::jsonb) INTO itens
  FROM (
    SELECT DISTINCT ON (chave) item, chave FROM (
      SELECT x.item, public.chave_codigo_red_importacao(x.item->>'codigo_red') AS chave, 1 AS prioridade
      FROM jsonb_array_elements(destino.termo_snapshot->'bens') x(item)
      UNION ALL
      SELECT x.item, public.chave_codigo_red_importacao(x.item->>'codigo_red'), 2
      FROM jsonb_array_elements(origem.termo_snapshot->'bens') x(item)
      UNION ALL
      SELECT jsonb_build_object('codigo_red', b.codigo_red, 'descricao', b.descricao, 'valor', b.valor, 'incorporacao', b.incorporacao, 'tipo', b.tipo), public.chave_codigo_red_importacao(b.codigo_red), 3
      FROM public.bens b WHERE b.id = ANY(ids)
    ) todos ORDER BY chave, prioridade
  ) escolhidos;
  UPDATE public.importacoes SET termo_snapshot = jsonb_set(jsonb_set(termo_snapshot, '{bens}', itens), '{bem_ids}', to_jsonb(ids)) WHERE id = destino.id;
  UPDATE public.bens SET importacao_id = destino.id WHERE id = ANY(ids) AND importacao_id IS DISTINCT FROM destino.id;
  GET DIAGNOSTICS movidos = ROW_COUNT;
  -- Movimentações anteriores do mesmo bem continuam no histórico, sem apagar registros de estorno.
  UPDATE public.transferencias_bens_itens t SET transferencia_id = destino.id, numero = destino.numero, termo_ano = destino.termo_ano
    WHERE t.transferencia_id = origem.id AND NOT EXISTS (
      SELECT 1 FROM public.transferencias_bens_itens d WHERE d.transferencia_id = destino.id AND d.bem_id = t.bem_id
    );
  UPDATE public.transferencias_bens_itens SET origem_importacao_id = destino.id WHERE origem_importacao_id = origem.id;
  IF EXISTS (SELECT 1 FROM public.bens WHERE importacao_id = origem.id) THEN RAISE EXCEPTION 'Há bens vinculados ao termo anterior. Nenhuma alteração foi realizada'; END IF;
  DELETE FROM public.entregas_termos WHERE importacao_id = origem.id;
  DELETE FROM public.importacoes WHERE id = origem.id;
  RETURN jsonb_build_object('destino', destino.id, 'numero', destino.numero, 'removido', origem.numero, 'movidos', movidos, 'quantidade', cardinality(ids));
END;
$function$
